<script setup lang="ts">
import {ref,onMounted} from 'vue';import {api,when} from './api';import Icon from './Icon.vue';import LarkSettings from './LarkSettings.vue';
const props=defineProps<{user:any}>(),emit=defineEmits(['notify','error','models']);
const tab=ref('models'),models=ref<any[]>([]),users=ref<any[]>([]),settings=ref<any>({lark:{},telegram:{},notifications:[]}),busy=ref(false),showModel=ref(false);
const projects=ref<any[]>([]),importForm=ref({projectId:'',url:'',title:''});
const model=ref({name:'',base_url:'',model:'',api_key:''}),lark=ref({appId:'',appSecret:''}),telegram=ref({token:'',chatIds:'',enabled:false,events:['requirement','comment'],template:'{project} · {event}\n{title}'}),account=ref({name:'',email:'',password:''}),password=ref({current:'',password:''});
const tabs=[{id:'models',name:'AI 模型',icon:'Sparkles'},{id:'lark',name:'Lark 文档',icon:'FileText'},{id:'telegram',name:'消息通知',icon:'Send'},{id:'users',name:'账号管理',icon:'Users'},{id:'security',name:'账号安全',icon:'Shield'}];
function confirmRemoval(){return window.confirm('确定移除此模型连接？');}
function navigate(url:string){window.location.assign(url);}
async function run(fn:()=>Promise<any>){busy.value=true;try{await fn();}catch(e:any){emit('error',e.message);}finally{busy.value=false;}}
async function load(){projects.value=await api('/projects');importForm.value.projectId=importForm.value.projectId||projects.value[0]?.id||'';models.value=await api('/models');settings.value=await api('/settings');lark.value.appId=settings.value.lark.appId;telegram.value={...telegram.value,...settings.value.telegram,token:''};if(props.user.admin)users.value=await api('/users');emit('models',models.value);}
onMounted(()=>run(load));
</script>
<template><div class="page-heading"><div><span class="eyebrow">MAKE IT YOURS</span><h1>设置与集成</h1><p>连接你的工具，让产品工作流顺畅运转。</p></div><span class="badge"><Icon name="Shield" :size="14"/>{{user.admin?'空间管理员':'团队成员'}}</span></div><div class="settings-layout"><nav class="settings-tabs"><button v-for="t in tabs.filter(t=>user.admin||!['users','telegram'].includes(t.id))" :class="{active:tab===t.id}" @click="tab=t.id"><Icon :name="t.icon"/>{{t.name}}</button></nav><section class="settings-content">
<template v-if="tab==='models'"><div class="section-title"><div><h2>AI 模型连接</h2><p class="muted">支持兼容 Chat Completions 协议的模型服务。</p></div><button v-if="user.admin" class="primary" @click="showModel=!showModel"><Icon name="Plus"/>添加模型</button></div><div class="settings-tip"><Icon name="Lock"/><p>API 密钥加密保存于服务端，不会传递到浏览器。生成内容使用你配置的真实模型。</p></div><form v-if="showModel" class="settings-form bordered" @submit.prevent="run(async()=>{await api('/models','POST',model);showModel=false;model={name:'',base_url:'',model:'',api_key:''};await load();emit('notify','AI 模型已保存')})"><div class="form-grid"><label>连接名称<input v-model="model.name" required placeholder="例如：产品创作模型"/></label><label>模型标识<input v-model="model.model" required placeholder="填写供应商提供的模型 ID"/></label></div><label>API Base URL<input v-model="model.base_url" type="url" required placeholder="https://你的服务地址/v1"/></label><label>API Key<input v-model="model.api_key" type="password" required autocomplete="off" placeholder="输入模型服务密钥"/></label><button class="primary" :disabled="busy">保存模型</button></form><div v-if="!models.length&&!showModel" class="empty-state"><span><Icon name="Sparkles" :size="32"/></span><h3>为你的创作接入 AI</h3><p>配置模型后，即可生成 PRD、技术文档与交互原型。<br>支持同一模型承担分析、评审和交付多个 Agent 角色。</p><button v-if="user.admin" class="secondary" @click="showModel=true">添加第一个模型<Icon name="ArrowRight" :size="15"/></button></div><article v-for="m in models" class="model-row"><span class="model-icon"><Icon name="Sparkles" :size="23"/></span><div><h3>{{m.name}}</h3><p>{{m.model}}</p><small>{{m.base_url}}</small></div><template v-if="user.admin"><button class="secondary" :disabled="busy" @click="run(async()=>{await api('/models/'+m.id+'/check','POST',{});emit('notify','模型连接成功，已收到真实响应')})">验证连接</button><button class="icon-button danger" title="删除模型" @click="run(async()=>{if(!confirmRemoval())return;await api('/models/'+m.id,'DELETE',{});await load()})"><Icon name="Trash2" :size="17"/></button></template></article><p class="settings-reference">接口参考：<a href="https://gpt-best.apifox.cn/" target="_blank" rel="noopener">AI 模型接口文档 <Icon name="ExternalLink" :size="12"/></a></p></template>
<LarkSettings v-if="tab==='lark'" @notify="emit('notify',$event)" @error="emit('error',$event)"/>
<template v-if="tab==='telegram'"><div class="integration-heading"><span class="integration-logo telegram"><Icon name="Send" :size="28"/></span><div><h2>Telegram 通知</h2><p>在团队熟悉的地方，及时收到需求和评审消息。</p></div><span class="badge" :class="settings.telegram.configured?'green':''">{{settings.telegram.configured?'已配置':'未配置'}}</span></div><form class="settings-form" @submit.prevent="run(async()=>{await api('/settings/telegram','POST',telegram);telegram.token='';await load();emit('notify','通知规则已保存')})"><label>Bot Token<input v-model="telegram.token" type="password" :placeholder="settings.telegram.configured?'已加密保存，留空保留原值':'通过 @BotFather 创建机器人并获取 Token'"/></label><label>接收目标 Chat ID<textarea v-model="telegram.chatIds" rows="3" placeholder="每行一个群组或用户 Chat ID；用户需先与机器人建立会话"/></label><label>消息模板<textarea v-model="telegram.template" rows="4" required/></label><small class="muted">可用变量：{project} 项目名称、{event} 事件名称、{title} 内容标题</small><div class="form-grid"><label class="check-label"><input type="checkbox" v-model="telegram.events" value="requirement"/>新需求通知</label><label class="check-label"><input type="checkbox" v-model="telegram.events" value="comment"/>评审意见通知</label></div><label class="check-label"><input type="checkbox" v-model="telegram.enabled"/>启用自动通知</label><button class="primary" :disabled="busy">保存通知设置</button></form><h3 class="spaced">投递记录</h3><div class="empty-mini" v-if="!settings.notifications.length">尚无通知投递记录；配置并启用后，真实事件将触发通知。</div><div v-for="n in settings.notifications" class="notification-row"><span class="badge" :class="n.status==='sent'?'green':'high'">{{n.status==='sent'?'已发送':'失败'}}</span><span>{{n.detail}}</span><small>{{when(n.created_at)}}</small></div></template>
<template v-if="tab==='users'"><h2>空间成员账号</h2><p class="muted">创建账号后，在项目成员中授予对应的访问权限。新账号默认没有项目权限。</p><div v-for="u in users" class="member-row"><span class="avatar">{{u.name.slice(0,1)}}</span><div><strong>{{u.name}}</strong><small>{{u.email}}</small></div><span class="badge">{{u.admin?'管理员':'成员'}}</span></div><form class="settings-form bordered" @submit.prevent="run(async()=>{await api('/users','POST',account);account={name:'',email:'',password:''};await load();emit('notify','账号已创建，请在项目中分配权限')})"><h3>创建成员账号</h3><div class="form-grid"><label>姓名<input v-model="account.name" required/></label><label>邮箱<input v-model="account.email" type="email" required/></label></div><label>初始密码<input v-model="account.password" type="password" minlength="12" required autocomplete="new-password" placeholder="至少 12 位，请通过可信方式交付给成员"/></label><button class="primary" :disabled="busy">创建账号</button></form></template>
<template v-if="tab==='security'"><h2>账号安全</h2><p class="muted">{{user.email}} · 修改密码后，其他设备的登录状态将失效。</p><form class="settings-form" @submit.prevent="run(async()=>{await api('/auth/password','POST',password);password={current:'',password:''};emit('notify','密码已更新，其他会话已退出')})"><label>当前密码<input type="password" v-model="password.current" required autocomplete="current-password"/></label><label>新密码<input type="password" v-model="password.password" required minlength="12" autocomplete="new-password" placeholder="至少 12 位"/></label><button class="primary" :disabled="busy">更新密码</button></form></template>
</section></div></template>
